s.AddSingleton<IPay, CardPay>();
s.AddSingleton<IPay, WalletPay>();
s.AddSingleton<PayService>();
var svc = s.BuildServiceProvider()
    .GetRequiredService<PayService>();
Console.WriteLine(svc.Pick(40_000));
Console.WriteLine(svc.Pick(90_000));

class CardPay : IPay { public bool CanHandle(int a) => a <= 100_000; }
class WalletPay : IPay { public bool CanHandle(int a) => a <= 50_000; }
class PayService(IEnumerable<IPay> all)
{
    public string Pick(int a) =>
        all.FirstOrDefault(x => x.CanHandle(a))
           ?.GetType().Name ?? "none";
}
